import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>GIF, bir dizi sabit görüntüden yapılmış döngü hâlinde oynayan kısa bir animasyondur. Sessiz oynar, sonsuza dek ya da sabit sayıda tekrarlanır ve neredeyse tüm sohbet uygulamalarında, sosyal akışlarda ve web sitelerinde çalışır. İyi yapılmış bir GIF iki saniyede bir paragrafın anlatamadığını söyler.</p>\n<p><a href=\"/tr/gif-olusturucu\">GIF Oluşturucu</a> fotoğraflarını tarayıcıda hareketli bir GIF'e dönüştürür. Kare olarak iki ya da daha fazla görüntü yükle, her karenin zamanlamasını belirle, tekrar sayısını seç ve filigransız bir GIF89a dosyası indir. Hiçbir şey sunucuya yüklenmez.</p>\n<p>Bu kılavuz GIF'lerin nasıl çalıştığını, karelerin nasıl seçilip zamanlanacağını ve dosya boyutunun paylaşmak için yeterince küçük nasıl tutulacağını açıklar. Tepki GIF'i, ürün demosu ya da öğretici klibi yapıyor ol; aynı ilkeler geçerlidir.</p>\n<h2 id=\"what-is-a-gif\">GIF nedir?</h2>\n<p>GIF, Graphics Interchange Format (Grafik Değişim Biçimi) anlamına gelir ve seksenlerin sonundan beri vardır. Günlük kullanımda kalan en eski görüntü biçimlerinden biridir ve kalıcılığını bir özelliğe borçludur: videosuz animasyon.</p>\n<p>Bir GIF bir dizi kare saklar; her biri kısa bir süre, birbiri ardına gösterilir. Oynatıcı kareler arasında döngü yapar ve sonuç kısa bir video klibi gibi görünür. Ses yoktur, oynatma kontrolleri yoktur ve video kodeki gerekmez.</p>\n<p>GIF'ler kare başına 256 renkle sınırlıdır; bu yüzden tam renkli fotoğraflardan çok çizimler, ekran görüntüleri ve basit animasyonlarla daha iyi gider. Fotoğraf GIF'i çalışır ama sınırlı palet degradeleri bantlı ve cilt tonlarını düz gösterebilir.</p>\n<p>Biçim evrenseldir. Sohbet uygulamaları, sosyal akışlar, forumlar, e-posta ve web siteleri GIF'leri özel bir oynatıcı olmadan gösterir. Bu evrensellik, GIF'in kısa bir animasyonu herkesle paylaşmanın en kolay yolu olmaya devam etmesinin nedenidir.</p>\n<h2 id=\"how-the-gif-maker-works\">GIF oluşturucu nasıl çalışır?</h2>\n<p>GIF oluşturucu fotoğraflarını tamamen tarayıcında hareketli bir GIF'e kodlar. Karelerin cihazından asla çıkmaz; bu görüntüler henüz yayımlanmamış ürün fotoğrafları ya da kişisel fotoğraflar olduğunda önemlidir. Yükleme yoktur, kuyruk yoktur ve sunucu beklemesi yoktur.</p>\n<p>Kare olarak iki ya da daha fazla görüntü yüklersin ve araç onları sıralar. Kareleri sürükleyerek yeniden sıralayabilir, daha uzun kalması için bir kareyi çoğaltabilir ve ait olmayan bir kareyi silebilirsin. Kare listesi animasyonunun zaman çizelgesidir.</p>\n<p>Her karenin saniyenin kesirleriyle ölçülen kendi gecikmesi vardır. Kısa bir gecikme animasyonu hızlı yapar ve uzun bir gecikme yavaş yapar. Tüm kareler için tek bir gecikme belirleyebilir ve ardından daha uzun kalması gereken tek tek kareleri ayarlayabilirsin.</p>\n<p>Canlı zamanlama önizlemesi animasyonu mevcut ayarınla oluşturmadan önce oynarken gösterir. Önizlemede gördüğün bitmiş GIF'te görülecek şeydir; bu yüzden indirmeden önce incele. Oluşturulan dosya, GIF'lerin desteklendiği her yerde oynayan standart bir GIF89a'dır.</p>\n<h2 id=\"choosing-frames\">Kareler nasıl seçilir?</h2>\n<p>Kareler animasyonu oluşturan sabit görüntülerdir ve kare seçimi GIF'in çalışıp çalışmayacağına karar verir. İyi bir GIF küçük bir hikâye anlatır: öncesi ve sonrası, dönen bir ürün, adım adım bir eylem ya da büyüyüp boşalan bir tepki.</p>\n<p>Boyut ve biçim bakımından benzer kareler kullan. Araç farklı oranlardaki görüntüleri işler ama eşit boyutlu bir kare seti zıplama ya da siyah bant olmadan pürüzsüz bir animasyon verir. Kareler çok farklıysa önce yeniden boyutlandır ya da kırp.</p>\n<p>Kare sayısını orta tut. Beş ila on beş karelik bir GIF genellikle tepki, demo ya da kısa bir öğretici adımı için yeterlidir. Daha fazla kare daha uzun bir animasyon ve daha büyük bir dosya demektir ve çok uzun bir GIF biçimi işleten gücü kaybeder.</p>\n<p>Sıra sayıdan daha önemlidir. Bir ürün dönüşü saat yönünde ya da tersi okunur, bir öğretici adım sırasında okunur ve bir tepki kurulum ve final olarak okunur. Hareketin doğal hissetmesi için kareleri sırala ve ardından önizlemeyi incele.</p>\n<h2 id=\"frame-delays-and-timing\">Kare gecikmeleri ve zamanlama</h2>\n<p>Kare gecikmesi her karenin ekranda ne kadar kaldığıdır ve animasyonun hissini kontrol eden ana kontroldür. Kare başına 0,1 saniyelik bir gecikme hızlı ve enerjik bir hareket verirken 0,5 saniyelik bir gecikme yavaş ve bilinçli bir hareket verir.</p>\n<p>Animasyonun gövdesi için tutarlı bir gecikme ve vurgu gerektiren kareler için daha uzun bir gecikme kullan. Başlangıçtaki bir başlık slaydı okunabilmesi için daha uzun kalmayı hak eder ve son kare mesajın döngü yeniden başlamadan önce yerleşmesi için daha uzun kalmayı hak eder.</p>\n<p>1, 2, 5 ve 10 kare/saniye hızlı hazır ayarları başlangıç noktaları verir. Saniyede bir kare her görüntünün tam bir bakışı hak ettiği yavaş bir slayt gösterisidir, saniyede beş kare çevik bir demoyu ve saniyede on kare basit hareketler için yeterince pürüzsüz olanı verir. Bir hazır ayardan başla ve ardından tek tek kareleri ayarla.</p>\n<p>Zamanlamayı canlı zamanlama önizlemesinde dene. Sayı olarak iyi görünen bir gecikme harekette kötü hissettirebilir ve önizleme gerçek hissi gösterir. Animasyon önemli kareden geçip giderse tüm GIF'i yavaşlatmak yerine o kareyi uzat.</p>\n<h2 id=\"frame-rate-presets\">Kare hızı hazır ayarları</h2>\n<p>Hazır ayarlar saniyedeki kareleri gecikmelere dönüştürür. Bir FPS her karenin bir saniye gösterildiği anlamına gelir; bu her görüntünün tam bir bakışı hak ettiği sabit görüntü slayt gösterisiyle iyi gider. İki FPS kare başına yarım saniye demektir; bu yavaş bir demo ile iyi gider.</p>\n<p>Beş FPS kare başına saniyenin beşte biri demektir; bu çoğu GIF için ideal noktadır. Hareket gibi hissetmek için yeterince hızlı ve her karenin kaydedilmesi için yeterince yavaştır. Ürün demoları, öğreticiler ve basit animasyonlar genellikle bu hızda yaşar.</p>\n<p>On FPS kare başına saniyenin onda biri demektir; bu aracın sunduğu en pürüzsüz olandır. Dönüş ya da yürüme döngüsü gibi akıcı görünmesi gereken hareketlerle iyi gider ama aynı zamanda saniyede daha fazla kare ve daha büyük bir dosya da demektir.</p>\n<p>Daha fazlası her zaman daha iyi değildir. Otuz kareli, saniyede on karelik bir GIF üç saniye sürer ve ağırdır, aynı fikir saniyede beş kare ve on beş kareyle üç saniye sürer ve yarı ağırlıktadır. Hızı harekete uydur, en yüksek değere değil.</p>\n<h2 id=\"loop-options\">Tekrar seçenekleri</h2>\n<p>Tekrar GIF'in kaç kez oynayacağına karar verir. Sonsuz döngü sonsuza dek oynar; bu GIF'in klasik davranışıdır ve tepkiler, süslemeler ve tekrar tekrar dikkat çekmesi gereken her şey için doğru seçimdir.</p>\n<p>Sonlu döngü sabit sayıda oynar ve ardından son karede durur. Bu kişinin animasyonun ortasındaki bir karede değil, son durumda bitmesi gereken öğretici ya da demo ile iyi gider. İki ya da üç tekrar sayısı sonsuza dek tekrarlanmadan ikinci bir bakış verir.</p>\n<p>Tek oynatma animasyonu bir kez gösterir ve durur. Bu animasyonun bir kezlik bir açılış olduğu bir mesajla iyi gider; örneğin sonrada bitmesi gereken bir önce-sonra. Kişi değişimi görür ve ardından sonuç kalır.</p>\n<p>Tekrarı bağlama göre seç. Sohbet tepkisi sonsuz döngü ister, ürün demosu birkaç tekrar ister ve öğretici adımı sonuçta bitmek ister. Yanlış tekrar iyi bir GIF'i kırık hissettirir.</p>\n<h2 id=\"frame-fit-contain-vs-cover\">Kare uydurma: sığdır ve kapla</h2>\n<p>Kare uydurma, kareler farklı oranlara sahip olduğunda ne olacağına karar verir. Sığdır her kareyi kırpmadan çıktı boyutuna uydurur; böylece karenin tamamı görülür ve boş alan kenar olur. Boş bantlar pahasına görüntünün tamamını korur.</p>\n<p>Kapla kareyi kırparak çıktı boyutunu tamamen doldurur; bu yüzden boş bant yoktur ama karenin kenarları kesilebilir. Bazı karelerin kenarlarını kaybetme pahasına temiz ve kenardan kenara bir animasyon verir.</p>\n<p>Her karenin her parçası önemli olduğunda, kırpılmış bir düğmenin adımı gizleyeceği bir öğretici gibi, Sığdır'ı seç. Animasyonun çerçeveyi temiz biçimde doldurması gerektiğinde, boş bantların bitmemiş görüneceği bir sosyal gönderi gibi, Kapla'yı seç.</p>\n<p>Çıktı genişliğini düzenlediğinde oran sabit kalır; bu yüzden genişliği değiştirmek tüm GIF'i germek yerine ölçekler. Çıktı boyutlarını bir kez belirle, uydurmayı seç ve kareler tutarlı biçimde izler.</p>\n<h2 id=\"output-size-and-dimensions\">Çıktı boyutu ve boyutları</h2>\n<p>Çıktı genişliği bitmiş GIF'in piksel genişliğini belirler ve yükseklik karelerin oranına bağlıdır. 480 piksel genişlik sohbet ve sosyal paylaşım için yaygın bir seçimdir, daha büyük bir genişlik ise web sitesi ya da sunumla iyi gider.</p>\n<p>GIF'ler için daha küçük genellikle daha iyidir. 480 piksel genişliğinde bir GIF hızlı paylaşılacak kadar küçük ve telefonda net görünecek kadar büyüktür. 1000 piksel genişliğinde bir GIF dört kat piksele ve birkaç kat dosya boyutuna sahiptir; çoğu kişinin fark etmeyeceği bir fark için.</p>\n<p>Araç çıktı boyutları için bir en düşük ve en yüksek belirler; bu yüzden uç boyutlar mümkün değildir. Çok küçük çıktılar ayrıntı kaybeder ve çok büyük çıktılar paylaşmak için çok büyük dosyalar oluşturur. En iyi denge için aralığın ortasına yakın kal.</p>\n<p>Boyutları hedefe karşı incele. Bir sohbet uygulaması zaten büyük bir GIF'i küçültebilir; bu yüzden dev bir dosya göndermek görünür kazanç olmadan veri boşa harcar. Web sitesi banner'ı sohbet etiketinden daha büyük bir genişliğe ihtiyaç duyar; bu yüzden boyutu yere uydur.</p>\n<h2 id=\"color-palette-quality\">Renk paleti kalitesi</h2>\n<p>GIF'ler kare başına en fazla 256 renk saklar; bu yüzden kodlayıcının hangi renklerin korunacağını seçmesi gerekir. Renk paleti kalite kontrolü bu seçimin ne kadar dikkatli olduğunu kontrol eder. Yüksek bir değer kareleri daha ayrıntılı analiz eder ve en önemli renkleri korur.</p>\n<p>Daha yüksek kalite daha pürüzsüz degradeler ve daha doğru cilt tonları verir ama kodlaması daha uzun sürer ve biraz daha büyük bir dosya üretebilir. Daha düşük kalite daha hızlı kodlar ve daha küçük dosyalar verir ama degradeler bantlanma gösterebilir ve ince renkler değişebilir.</p>\n<p>Fotoğraflar için yüksek palet kalitesi kullan. Fotoğrafların binlerce rengi vardır ve dikkatli bir palet görüntüyü tanınabilir tutar. Az renkli çizimler ve ekran görüntüleri için düşük bir değer yeterlidir, çünkü palet zaten tüm renkleri saklayabilir.</p>\n<p>Paleti bir degrade ya da yüz içeren bir karede dene. Bunlar zayıf bir paletin ilk fark edildiği yerlerdir; gökyüzünde bantlar ya da ciltte lekeler gibi. Deneme karesi temiz görünüyorsa GIF'in geri kalanı da temiz olur.</p>\n<h2 id=\"large-gif-warning\">Büyük GIF uyarısı</h2>\n<p>Araç tahmini boyut 5 MB ya da 15 MB'yi geçtiğinde büyük GIF uyarısı gösterir. Bu eşikler vardır, çünkü büyük GIF'leri paylaşmak zordur: sohbetlerde yavaş yüklenir, yükleme sınırları tarafından reddedilebilir ve mobil veri tüketir.</p>\n<p>Bir GIF üç nedenle büyür: çok kare, büyük boyutlar ya da yüksek kare hızı. Üçünden birini kesmek dosyayı küçültür. Daha az kare genellikle en iyi kesimdir, çünkü daha kısa bir GIF aynı zamanda daha iyi bir GIF'tir.</p>\n<p>Uyarı göründüğünde önce çıktı genişliğini küçült. Genişliği yarıya indirmek piksel sayısını dörtte bire indirir; bu mevcut en büyük tasarruftur. Ardından uyarı kaybolana kadar kare sayısını ya da hızı azalt.</p>\n<p>GIF'in büyük kalması gerekiyorsa GIF'in doğru biçim olup olmadığını düşün. MP4 biçiminde kısa bir video aynı animasyondan çok daha küçüktür ve çoğu platform video kabul eder.</p>\n<p><a href=\"/tr/gif-sikistir\">GIF Sıkıştırıcı</a> bitmiş bir GIF'i küçültebilir ama boyut ana sorunsa video en iyi seçimdir.</p>\n<h2 id=\"transparency-in-gifs\">GIF'lerde şeffaflık</h2>\n<p>GIF'ler şeffaflığı destekler ama yalnızca tek bir şeffaf renk olarak, pürüzsüz bir alfa kanalı olarak değil. Bir piksel tamamen şeffaf ya da tamamen opaktır; bu yüzden yumuşak kenarlar ve gölgeler şeffaf bir arka plan karşısında sert olur.</p>\n<p>GIF oluşturucu, çıktı buna ayarlandığında PNG karelerindeki şeffaf arka planları korur. Şeffaflığı olan bir logo ya da etiket şeffaf bölgelerini korur; bu her arka plan üzerinde oturması gereken katmanlar ve sohbet etiketleriyle iyi gider.</p>\n<p>Yumuşak kenarlar dikkat ister. Gölgeli ya da bulanık kenarlı bir logo, şeffaflık tek bir renge indirildiğinde hale gösterir, çünkü yarı şeffaf pikseller katı ya da şeffaf olmalıdır. Sert kenarlı bir grafik yumuşak olandan daha iyi çalışır.</p>\n<p>Şeffaf bir GIF'i açık bir arka plan ve koyu bir arka plan üzerinde dene. Beyaz üzerinde görünmez bir hale siyah üzerinde açık olabilir ve tersi de geçerlidir. Hale görünüyorsa grafiği şeffaflık kullanmak yerine katı bir renk üzerinde düzleştir.</p>\n<h2 id=\"common-mistakes\">Yaygın hatalar</h2>\n<p>En yaygın hata çok fazla karedir. Elli kareli bir GIF kılık değiştirmiş bir videodur ve ağır, yavaş ve sıkıcı olur. Kare listesini temel anlara kırp; GIF aynı anda daha keskin ve daha küçük olur.</p>\n<p>Bir başka hata her kare için eşit bir gecikmedir. Saniyenin onda biri gösterilen bir başlık slaydı okunamaz ve saniyenin onda biri gösterilen bir son kare yerleşemez. Önemli karelere daha uzun gecikmeler ve hareket karelerine daha kısa gecikmeler ver.</p>\n<p>Üçüncü bir hata dev bir çıktı boyutudur. Sohbet mesajı için 1000 piksel genişliğinde dışa aktarılan bir GIF, 500 piksel sürümün dört kat pikseline sahiptir ve sohbet uygulaması onu zaten küçültecektir. Boyutu hedefe uydur.</p>\n<p>Son olarak birçok kişi fotoğraf GIF'lerinde palet kalitesini görmezden gelir. Düşük bir palet değeri fotoğrafı posterleşmiş bir felakete dönüştürür; bantlı gökyüzü ve lekeli cilt olur. Fotoğraflar için palet kalitesini yükselt ve düşük değeri yalnızca basit grafikler için koru.</p>\n<h2 id=\"quick-reference\">Hızlı başvuru: GIF oluşturucu kontrol listesi</h2>\n<p>Eşit boyutlu beş ila on beş kare seç, onları hikâye düzeninde sırala ve saniyede yaklaşık beş karelik bir temel gecikme belirle. Başlık ve son karelere daha uzun beklemeler ver ve tekrar sayısını bağlama göre seç.</p>\n<p>Çıktı genişliğini hedefe göre belirle, her ayrıntı önemli olduğunda Sığdır'ı ve çerçevenin temiz doldurulması gerektiğinde Kapla'yı kullan ve fotoğraflar için palet kalitesini yükselt. Büyük GIF uyarısına kulak ver ve önce genişliği küçült.</p>\n<p>Adım adım oluşturma için <a href=\"/tr/blog/gorsellerden-gif-nasil-olusturulur\">Görüntülerden GIF Nasıl Yapılır?</a> yazısını oku ve boyut dengesi ayrıntısı için <a href=\"/tr/blog/gif-kare-hizi-dosya-boyutu\">GIF Kare Hızı ve Dosya Boyutu: Akıcı mı, Küçük mü?</a> yazısını oku. GIF'ini <a href=\"/tr/gif-olusturucu\">GIF Oluşturucu</a> ile oluştur.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"GIF nedir ve videodan farkı nedir?","answer":"GIF, döngü hâlinde oynayan, sessiz ve oynatma kontrolü olmayan bir dizi sabit görüntüdür. Video hareketi ve sesi çok daha küçük bir dosyaya sıkıştırmak için bir kodek kullanır. GIF'ler daha büyüktür ama oynatıcısız her yerde oynar; bu yüzden sohbetlere ve sosyal akışlara hâkimdir."},{"question":"Bir GIF kaç kare içermelidir?","answer":"Beş ila on beş kare çoğu GIF için yeterlidir: tepki, ürün demosu ya da kısa bir öğretici adımı. Daha fazla kare daha uzun bir animasyon ve daha büyük bir dosya demektir. GIF'in elli kareye ihtiyacı varsa muhtemelen bir videodur ve video biçimi ona daha iyi gider."},{"question":"GIF dosyaları neden bu kadar büyüktür?","answer":"GIF'ler her kareyi 256 renk paletiyle tam bir görüntü olarak saklar ve videoyla karşılaştırıldığında kötü sıkıştırır. Çok kare, büyük boyutlar ve yüksek hız boyut toplar. Bir GIF'i hızlı küçültmek için önce genişliği, ardından kare sayısını azalt."},{"question":"Videodan GIF oluşturabilir miyim?","answer":"GIF oluşturucu videodan değil, sabit görüntülerden GIF kurar. Bir videoyu GIF'e dönüştürmek için önce videodan bir dizi sabit kare çıkar ve ardından bu kareleri GIF'in kareleri olarak yükle. İstediğin hareketi taşıyan kareleri seç."},{"question":"GIF'ler tüm sosyal platformlarda çalışır mı?","answer":"Neredeyse hepsinde. Sohbet uygulamaları, sosyal akışlar, forumlar ve e-posta GIF'leri özel oynatıcı olmadan gösterir. Bazı platformlar yüklenen GIF'leri otomatik olarak videoya dönüştürür ama animasyon yine de oynar; bu yüzden izleyen için sonuç aynıdır."},{"question":"GIF için en iyi boyut nedir?","answer":"Yaklaşık 480 piksel genişlik sohbet ve sosyal paylaşım için iyi bir varsayılandır: hızlı gönderilecek kadar küçük ve telefonda net görünecek kadar büyük. Daha büyük bir genişliği yalnızca GIF'in daha büyük gösterildiği bir web sitesi ya da sunum için kullan."}];
